/**
 * Result types for conversation practice.
 *
 * Every non-success outcome — the backend not running, a non-2xx response,
 * a request that never settles — collapses into the single `"unavailable"`
 * member. The caller only ever needs to know *that* the backend isn't
 * answering, not *why*; a richer error type would be unused detail carried
 * through every future consumer of the port.
 *
 * "Unavailable" is a member of the union rather than a thrown error on
 * purpose: encoding it in the type makes the compiler force every caller to
 * handle it, so "never asked" and "asked and failed" can't quietly become
 * indistinguishable the way they do when a caller forgets a try/catch.
 */

/** The AI partner's opening turn: Thai text plus playable audio. */
export type ConversationOpeningResult =
	| { status: "ok"; questionText: string; questionAudioUrl: string }
	| { status: "unavailable" };

/**
 * A judgement of one spoken reply.
 *
 * `"unscored"` is a *system-side* failure (unparseable judge output, a
 * transcription error) — never a learner's wrong answer, so a backend
 * hiccup is never rendered as, or later tallied as, the learner's mistake.
 */
export type ConversationVerdict = "pass" | "fail" | "unscored";

export type ConversationJudgeResult =
	| {
			status: "ok";
			transcript: string;
			verdict: ConversationVerdict;
			feedbackEn: string;
	  }
	| { status: "unavailable" };
import type {
	ConversationJudgeResult,
	ConversationOpeningResult,
} from "../conversation/types";

/**
 * The conversation practice backend, as the domain sees it: ask for the
 * opening turn, submit a spoken reply, get it judged.
 *
 * Neither method rejects — an unreachable or failing backend arrives as the
 * `"unavailable"` member of the result union (see `domain/conversation/types`).
 */
export interface ConversationPracticePort {
	getOpening(): Promise<ConversationOpeningResult>;
	judgeReply(
		questionText: string,
		replyAudio: Blob,
	): Promise<ConversationJudgeResult>;
}
---
import type {
	ConversationJudgeResult,
	ConversationOpeningResult,
	ConversationVerdict,
} from "../../domain/conversation/types";
import type { ConversationPracticePort } from "../../domain/ports/ConversationPracticePort";

/**
 * Where the local conversation backend listens (`docs/conversation-backend-api.md`).
 * A module constant, not user-configurable: the backend is a local-only,
 * single-user process, and the deployed GitHub Pages build can't reach it at
 * all — which is exactly the `"unavailable"` path below.
 */
export const CONVERSATION_BACKEND_BASE_URL = "http://localhost:8000";

/**
 * Generous on purpose: a cold backend loads Whisper, a 7B judge model and
 * TTS before it answers, and a judged reply is seconds of real GPU work. The
 * deadline exists so a request that never settles can't wedge the page
 * forever, not to police latency.
 */
export const CONVERSATION_REQUEST_TIMEOUT_MS = 60_000;

function isString(value: unknown): value is string {
	return typeof value === "string";
}

function isVerdict(value: unknown): value is ConversationVerdict {
	return value === "pass" || value === "fail" || value === "unscored";
}

function asRecord(value: unknown): Record<string, unknown> | null {
	return typeof value === "object" && value !== null
		? (value as Record<string, unknown>)
		: null;
}

/**
 * One request, with every failure flattened to `null`.
 *
 * `null` means "the backend did not answer with a usable body" and covers
 * all three failure shapes the port collapses together: `fetch` rejecting
 * (backend not running), a non-2xx status — checked *before* the body is
 * parsed, since a `500`/`422`/`404` resolves perfectly happily from
 * `fetch`'s point of view — and a request that never settles.
 *
 * The deadline is raced rather than left to the `AbortController` alone: the
 * controller is what actually cancels the in-flight request, but racing is
 * what guarantees this function returns even if nothing ever honours the
 * signal.
 */
async function fetchJson(
	path: string,
	init: RequestInit = {},
): Promise<unknown> {
	const controller = new AbortController();
	let timer: ReturnType<typeof setTimeout> | undefined;
	const deadline = new Promise<null>((resolve) => {
		timer = setTimeout(() => {
			controller.abort();
			resolve(null);
		}, CONVERSATION_REQUEST_TIMEOUT_MS);
	});
	const attempt = (async (): Promise<unknown> => {
		const response = await fetch(`${CONVERSATION_BACKEND_BASE_URL}${path}`, {
			...init,
			signal: controller.signal,
		});
		return response.ok ? await response.json() : null;
	})().catch(() => null);

	try {
		return await Promise.race([attempt, deadline]);
	} finally {
		clearTimeout(timer);
	}
}

/** base64 → a `blob:` URL an `<audio>`/`new Audio(url)` can play. */
function toBlobUrl(base64: string, mimeType: string): string {
	const binary = atob(base64);
	const bytes = new Uint8Array(binary.length);
	for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
	return URL.createObjectURL(new Blob([bytes], { type: mimeType }));
}

/** A recorded `Blob` → base64, chunked so a long take can't blow the stack. */
async function toBase64(blob: Blob): Promise<string> {
	const bytes = new Uint8Array(await blob.arrayBuffer());
	const CHUNK = 0x8000;
	let binary = "";
	for (let offset = 0; offset < bytes.length; offset += CHUNK) {
		binary += String.fromCharCode(...bytes.subarray(offset, offset + CHUNK));
	}
	return btoa(binary);
}

/**
 * `ConversationPracticePort` over the local backend's HTTP contract
 * (`docs/conversation-backend-api.md`).
 *
 * Audio crosses the wire as base64 paired with the MIME type it was actually
 * encoded as, in both directions — never an assumed `audio/wav`. Outbound
 * that means the recorded `Blob`'s own `.type`, because `useMicRecorder` has
 * no fixed output format (Chromium gives `audio/webm;codecs=opus`); inbound
 * it means the response's declared `question_audio_mime_type`.
 */
export class HttpConversationPracticeClient
	implements ConversationPracticePort
{
	async getOpening(): Promise<ConversationOpeningResult> {
		const body = asRecord(await fetchJson("/conversation/opening"));
		if (!body) return { status: "unavailable" };

		const { question_text, question_audio_base64, question_audio_mime_type } =
			body;
		if (
			!isString(question_text) ||
			!isString(question_audio_base64) ||
			!isString(question_audio_mime_type)
		) {
			return { status: "unavailable" };
		}

		try {
			return {
				status: "ok",
				questionText: question_text,
				questionAudioUrl: toBlobUrl(
					question_audio_base64,
					question_audio_mime_type,
				),
			};
		} catch {
			// Undecodable base64 is a backend that isn't answering usefully.
			return { status: "unavailable" };
		}
	}

	async judgeReply(
		questionText: string,
		replyAudio: Blob,
	): Promise<ConversationJudgeResult> {
		let replyAudioBase64: string;
		try {
			replyAudioBase64 = await toBase64(replyAudio);
		} catch {
			return { status: "unavailable" };
		}

		const body = asRecord(
			await fetchJson("/conversation/judge", {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({
					question_text: questionText,
					reply_audio_base64: replyAudioBase64,
					reply_audio_mime_type: replyAudio.type,
				}),
			}),
		);
		if (!body) return { status: "unavailable" };

		const { transcript, verdict, feedback_en } = body;
		if (
			!isString(transcript) ||
			!isVerdict(verdict) ||
			!isString(feedback_en)
		) {
			return { status: "unavailable" };
		}

		return { status: "ok", transcript, verdict, feedbackEn: feedback_en };
	}
}
---
// @vitest-environment jsdom
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	CONVERSATION_BACKEND_BASE_URL,
	CONVERSATION_REQUEST_TIMEOUT_MS,
	HttpConversationPracticeClient,
} from "./HttpConversationPracticeClient";

/** Blobs handed to `URL.createObjectURL`, newest last. */
let objectUrlBlobs: Blob[] = [];

function jsonResponse(body: unknown, status = 200): Response {
	return {
		ok: status >= 200 && status < 300,
		status,
		json: async () => body,
	} as unknown as Response;
}

function stubFetch(impl: (...args: unknown[]) => unknown) {
	const spy = vi.fn(impl);
	globalThis.fetch = spy as unknown as typeof fetch;
	return spy;
}

beforeEach(() => {
	objectUrlBlobs = [];
	URL.createObjectURL = (blob: Blob) => {
		objectUrlBlobs.push(blob);
		return `blob:stub/${objectUrlBlobs.length}`;
	};
	URL.revokeObjectURL = () => {};
});

afterEach(() => {
	vi.useRealTimers();
	vi.restoreAllMocks();
});

describe("HttpConversationPracticeClient.getOpening", () => {
	it("GETs the contracted opening endpoint and decodes the audio with the response's own MIME type", async () => {
		const audioBytes = Uint8Array.from([0xde, 0xad, 0xbe, 0xef]);
		const fetchSpy = stubFetch(async () =>
			jsonResponse({
				question_text: "สบายดีไหม",
				question_audio_base64: btoa(String.fromCharCode(...audioBytes)),
				question_audio_mime_type: "audio/wav",
			}),
		);

		const result = await new HttpConversationPracticeClient().getOpening();

		const [url, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
		expect(url).toBe(`${CONVERSATION_BACKEND_BASE_URL}/conversation/opening`);
		expect(init.method ?? "GET").toBe("GET");

		expect(result).toEqual({
			status: "ok",
			questionText: "สบายดีไหม",
			questionAudioUrl: "blob:stub/1",
		});
		// The blob behind that URL carries the declared MIME type and the
		// decoded bytes — not an assumed `audio/wav` and not the base64 text.
		expect(objectUrlBlobs).toHaveLength(1);
		expect(objectUrlBlobs[0].type).toBe("audio/wav");
		expect(new Uint8Array(await objectUrlBlobs[0].arrayBuffer())).toEqual(
			audioBytes,
		);
	});

	it("uses a non-WAV declared MIME type verbatim", async () => {
		stubFetch(async () =>
			jsonResponse({
				question_text: "สบายดีไหม",
				question_audio_base64: btoa("x"),
				question_audio_mime_type: "audio/mpeg",
			}),
		);

		await new HttpConversationPracticeClient().getOpening();

		expect(objectUrlBlobs[0].type).toBe("audio/mpeg");
	});
});

describe("HttpConversationPracticeClient.judgeReply", () => {
	it("POSTs the contracted body including the recorded blob's own MIME type, and maps the response into the domain verdict shape", async () => {
		const fetchSpy = stubFetch(async () =>
			jsonResponse({
				transcript: "สบายดีค่ะ",
				verdict: "pass",
				feedback_en: "Correct — a natural, on-topic reply.",
			}),
		);
		const reply = new Blob([Uint8Array.from([1, 2, 3])], {
			type: "audio/webm;codecs=opus",
		});

		const result = await new HttpConversationPracticeClient().judgeReply(
			"สบายดีไหม",
			reply,
		);

		const [url, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
		expect(url).toBe(`${CONVERSATION_BACKEND_BASE_URL}/conversation/judge`);
		expect(init.method).toBe("POST");
		expect(JSON.parse(init.body as string)).toEqual({
			question_text: "สบายดีไหม",
			reply_audio_base64: btoa(String.fromCharCode(1, 2, 3)),
			reply_audio_mime_type: "audio/webm;codecs=opus",
		});

		expect(result).toEqual({
			status: "ok",
			transcript: "สบายดีค่ะ",
			verdict: "pass",
			feedbackEn: "Correct — a natural, on-topic reply.",
		});
	});

	it("maps the contract's third verdict, unscored, rather than collapsing it into fail", async () => {
		stubFetch(async () =>
			jsonResponse({
				transcript: "",
				verdict: "unscored",
				feedback_en: "The judge's answer could not be read.",
			}),
		);

		const result = await new HttpConversationPracticeClient().judgeReply(
			"สบายดีไหม",
			new Blob([Uint8Array.from([1])], { type: "audio/ogg" }),
		);

		expect(result).toEqual({
			status: "ok",
			transcript: "",
			verdict: "unscored",
			feedbackEn: "The judge's answer could not be read.",
		});
	});
});

describe("HttpConversationPracticeClient — the backend not answering", () => {
	it("resolves both calls to unavailable when fetch rejects because the backend is not running", async () => {
		stubFetch(async () => {
			throw new TypeError("Failed to fetch");
		});
		const client = new HttpConversationPracticeClient();

		await expect(client.getOpening()).resolves.toEqual({
			status: "unavailable",
		});
		await expect(
			client.judgeReply("สบายดีไหม", new Blob([], { type: "audio/webm" })),
		).resolves.toEqual({ status: "unavailable" });
	});

	for (const status of [500, 422, 404]) {
		// The body here is deliberately *well-formed* — the contracted
		// success fields, returned under an error status. That is the only
		// body shape that can tell "checks `response.ok` first" apart from
		// "parses whatever came back": an error envelope fails field
		// validation anyway, so it would pass either way. The status is
		// authoritative; a body that happens to look right does not make a
		// 500 a success.
		it(`treats a ${status} response as unavailable even when its body is contract-shaped`, async () => {
			stubFetch(async (_url, init) =>
				jsonResponse(
					(init as RequestInit | undefined)?.method === "POST"
						? {
								transcript: "สบายดีค่ะ",
								verdict: "pass",
								feedback_en: "Correct.",
							}
						: {
								question_text: "สบายดีไหม",
								question_audio_base64: btoa("x"),
								question_audio_mime_type: "audio/wav",
							},
					status,
				),
			);
			const client = new HttpConversationPracticeClient();

			await expect(client.getOpening()).resolves.toEqual({
				status: "unavailable",
			});
			await expect(
				client.judgeReply("สบายดีไหม", new Blob([], { type: "audio/webm" })),
			).resolves.toEqual({ status: "unavailable" });
		});
	}

	it("treats a non-2xx with an unparseable body as unavailable, never an unhandled parse error", async () => {
		stubFetch(async () => ({
			ok: false,
			status: 500,
			json: async () => {
				throw new SyntaxError("Unexpected token < in JSON at position 0");
			},
		}));

		await expect(
			new HttpConversationPracticeClient().getOpening(),
		).resolves.toEqual({ status: "unavailable" });
	});

	it("treats a 200 whose body is missing the contracted fields as unavailable, never ok with a garbage verdict", async () => {
		stubFetch(async () => jsonResponse({ verdict: "maybe" }));

		await expect(
			new HttpConversationPracticeClient().judgeReply(
				"สบายดีไหม",
				new Blob([], { type: "audio/webm" }),
			),
		).resolves.toEqual({ status: "unavailable" });
	});

	it("resolves to unavailable within the bounded timeout when the request never settles", async () => {
		vi.useFakeTimers();
		stubFetch(() => new Promise(() => {}));

		const pending = new HttpConversationPracticeClient().getOpening();
		let settled = false;
		void pending.then(() => {
			settled = true;
		});

		await vi.advanceTimersByTimeAsync(CONVERSATION_REQUEST_TIMEOUT_MS - 1);
		expect(settled).toBe(false);

		await vi.advanceTimersByTimeAsync(2);
		expect(settled).toBe(true);
		await expect(pending).resolves.toEqual({ status: "unavailable" });
	});
});
---
import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "@/presentation/components/ui/button";
import type {
	ConversationJudgeResult,
	ConversationOpeningResult,
	ConversationVerdict,
} from "../../domain/conversation/types";
import { useApp } from "../hooks/useApp";
import { useMicRecorder } from "../hooks/useMicRecorder";

/**
 * How each verdict reads. `"unscored"` is deliberately neither of the other
 * two: it is the backend admitting it could not judge the turn, so showing
 * it as a fail would blame the learner for a system fault, and showing it as
 * a pass would be a lie.
 */
const VERDICT_PRESENTATION: Record<
	ConversationVerdict,
	{ label: string; note: string; color: string }
> = {
	pass: {
		label: "Good answer",
		note: "That works as a reply.",
		color: "var(--color-success, #15803d)",
	},
	fail: {
		label: "Not quite",
		note: "That does not answer the question yet — try again.",
		color: "var(--color-danger, #b91c1c)",
	},
	unscored: {
		label: "Could not be scored",
		note: "Something went wrong on the backend, so this turn was not judged. It does not count against you.",
		color: "var(--color-text-muted, #6b7280)",
	},
};

const BACKEND_UNAVAILABLE_MESSAGE =
	"The conversation backend is not running, so there is nothing to talk to yet. Start it locally and reload this page.";

/**
 * Spoken conversation practice: hear one Thai question, record a reply, see
 * whether the local backend judged it as an acceptable answer.
 *
 * Phase 1 asks exactly one hardcoded question — real, vocabulary-scoped
 * content is phase 2's job. There is deliberately no self-rating, no SRS
 * card and no history entry: a judge verdict is a different kind of signal
 * from a recall rating, and how it should feed the scheduler, if at all, is
 * not this task's call to make.
 */
export function ConversationPracticePage() {
	const { conversationPractice } = useApp();
	const [opening, setOpening] = useState<ConversationOpeningResult | null>(
		null,
	);
	const [judgement, setJudgement] = useState<ConversationJudgeResult | null>(
		null,
	);
	const [judging, setJudging] = useState(false);
	const { state, audioBlob, start, stop, reset } = useMicRecorder();
	const audioRef = useRef<HTMLAudioElement | null>(null);

	useEffect(() => {
		let cancelled = false;
		conversationPractice.getOpening().then((result) => {
			if (!cancelled) setOpening(result);
		});
		return () => {
			cancelled = true;
		};
	}, [conversationPractice]);

	const questionText = opening?.status === "ok" ? opening.questionText : null;
	const questionAudioUrl =
		opening?.status === "ok" ? opening.questionAudioUrl : null;

	// One finished take → one judgement. Keyed on the blob's identity, so a
	// re-render never re-submits the same recording.
	useEffect(() => {
		if (state !== "stopped" || !audioBlob || !questionText) return;
		let cancelled = false;
		setJudging(true);
		conversationPractice.judgeReply(questionText, audioBlob).then((result) => {
			if (cancelled) return;
			setJudgement(result);
			setJudging(false);
		});
		return () => {
			cancelled = true;
		};
	}, [state, audioBlob, questionText, conversationPractice]);

	// Same replay convention as SentenceListeningChallenge /
	// SymbolDictationChallenge: a fresh `Audio` per press, the previous one
	// stopped first, rejections swallowed (autoplay policy).
	const playQuestion = useCallback(() => {
		if (!questionAudioUrl) return;
		if (audioRef.current) {
			audioRef.current.pause();
			audioRef.current.currentTime = 0;
		}
		const audio = new Audio(questionAudioUrl);
		audioRef.current = audio;
		audio.play().catch(() => {});
	}, [questionAudioUrl]);

	useEffect(
		() => () => {
			audioRef.current?.pause();
			audioRef.current = null;
		},
		[],
	);

	function tryAgain() {
		setJudgement(null);
		reset();
	}

	if (opening === null) {
		return <p className="p-4">Connecting to the conversation backend…</p>;
	}

	// No question means nothing to reply to — so no record control at all,
	// rather than one that would silently do nothing.
	if (opening.status === "unavailable") {
		return (
			<div className="space-y-4 p-4">
				<h1 className="text-xl font-semibold">Conversation practice</h1>
				<p role="alert">{BACKEND_UNAVAILABLE_MESSAGE}</p>
			</div>
		);
	}

	return (
		<div className="space-y-6 p-4">
			<h1 className="text-xl font-semibold">Conversation practice</h1>

			<section className="space-y-3 text-center">
				<p className="text-3xl" lang="th">
					{opening.questionText}
				</p>
				<button
					type="button"
					onClick={playQuestion}
					aria-label="Play question"
					className="inline-flex items-center justify-center w-20 h-20 rounded-full text-4xl"
					style={{
						background: "var(--color-surface-2)",
						color: "var(--color-primary)",
					}}
				>
					🔊
				</button>
			</section>

			<section className="space-y-3">
				{state === "idle" && <Button onClick={start}>Record your reply</Button>}
				{state === "recording" && (
					<Button onClick={stop}>Stop recording</Button>
				)}
				{state === "denied" && (
					<p role="alert">
						Microphone access needed — allow the microphone in your browser,
						then try recording again.
					</p>
				)}
				{state === "error" && (
					<p role="alert">
						Your microphone could not be started. Check that a recording device
						is connected and try again.
					</p>
				)}
				{state === "stopped" && judging && <p>Judging your reply…</p>}
				{state === "stopped" && judgement?.status === "unavailable" && (
					<p role="alert">{BACKEND_UNAVAILABLE_MESSAGE}</p>
				)}
				{state === "stopped" && judgement?.status === "ok" && (
					<div className="space-y-1">
						<p style={{ color: VERDICT_PRESENTATION[judgement.verdict].color }}>
							<strong>{VERDICT_PRESENTATION[judgement.verdict].label}</strong>
						</p>
						<p>{VERDICT_PRESENTATION[judgement.verdict].note}</p>
						<p>
							We heard: <span lang="th">{judgement.transcript}</span>
						</p>
						<p>{judgement.feedbackEn}</p>
					</div>
				)}
				{state === "stopped" && !judging && (
					<Button onClick={tryAgain}>Record another reply</Button>
				)}
			</section>
		</div>
	);
}

