641	// --- Conversation practice port stub ---
642	
643	/**
644	 * A `ConversationPracticePort` that answers with whatever the test sets and
645	 * records what it was asked. Defaults to `"unavailable"` on both calls — the
646	 * honest default for a harness with no backend behind it.
647	 */
648	export class StubConversationPracticePort implements ConversationPracticePort {
649		opening: ConversationOpeningResult = { status: "unavailable" };
650		judgement: ConversationJudgeResult = { status: "unavailable" };
651		readonly judgeCalls: { questionText: string; replyAudio: Blob }[] = [];
652	
653		async getOpening(): Promise<ConversationOpeningResult> {
654			return this.opening;
655		}
656	
657		async judgeReply(
658			questionText: string,
659			replyAudio: Blob,
660		): Promise<ConversationJudgeResult> {
661			this.judgeCalls.push({ questionText, replyAudio });
662			return this.judgement;
663		}
664	}
